import test,{mock} from 'node:test';import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';import {JSDOM} from 'jsdom';
const html=await readFile(new URL('../dist/index.html',import.meta.url),'utf8'),catalog=JSON.parse(await readFile(new URL('../dist/catalog.json',import.meta.url))),ke=JSON.parse(await readFile(new URL('europe-packed.json',import.meta.url))),oz=JSON.parse(await readFile(new URL('asiana-packed.json',import.meta.url)));
// The checked-in calendar fixtures were observed on October 31; keep UI regressions independent of wall-clock time.
mock.timers.enable({apis:['Date'],now:new Date('2026-10-31T14:59:00Z')});
let serial=0;const waitFor=async condition=>{for(let n=0;n<300;n++){if(condition())return;await new Promise(r=>setTimeout(r,5));}throw new Error('UI condition was not reached');};
// Constructed all-operator proof/detail data keep unrelated UI regressions explicit.
// They are test inputs and never deployed as airline operating evidence.
const TEST_FIELDS=['economyAward','premiumAward','prestigeAward','premiumUpgrade','prestigeUpgrade','firstCombined'];
function testNumber(c){return c.origin==='ICN'&&['LHR','BKK'].includes(c.destination)?'KE907':['LHR','BKK'].includes(c.origin)&&c.destination==='ICN'?'KE908':'KE1';}
function addFlightDetails(records){for(const payload of Object.values(records.records)){const c=payload.current;c.flightDetailPolicyVersion=1;for(const d of c.dates){const positive=d.status==='OBSERVED'&&TEST_FIELDS.some(f=>d[f]);d.flightDetailStatus=d.status!=='OBSERVED'?'UNKNOWN':positive?'CAPTURED':'NO_MARKS';d.flights=positive?[{number:testNumber(c),departureTime:'12:00',...Object.fromEntries(TEST_FIELDS.map(f=>[f,d[f]]))}]:[];if(positive){d.flightDetailDate=d.date;d.flightDetailObservedAt='2026-10-31T14:00:00Z';}}}return records;}
function operatingProofFor(records){const weeks=new Map();for(const payload of Object.values(records.records))for(const day of payload.current.dates){const dt=new Date(day.date+'T00:00:00Z');dt.setUTCDate(dt.getUTCDate()-(dt.getUTCDay()+6)%7);const start=dt.toISOString().slice(0,10),origin=payload.current.origin,destination=payload.current.destination,key=origin+':'+destination+':'+start;if(weeks.has(key))continue;weeks.set(key,{schema:2,completeOperators:true,carrier:'KE',origin,destination,queriedDate:start,weekStart:start,observedAt:'2026-10-31T14:00:00Z',sourceUrl:'https://www.koreanair.com/flight-status',ownFlightRows:1,partnerFlightRows:0,dates:Array.from({length:7},(_,i)=>({date:new Date(dt.getTime()+i*86400000).toISOString().slice(0,10),status:'OPERATING',flights:[{number:testNumber(payload.current),operatorCode:'KE',operatorName:'대한항공',serviceKind:'DIRECT',departureTime:'12:00',arrivalTime:'18:00',status:'OPERATING'}]}))});}return {schema:1,weeks:[...weeks.values()]};}
async function page({holdAsiana=false,denyAsiana=false,keData=ke,ozData=oz,denyKorean=false,operationPolicy=null,denyOperation=false,timetableReference=null,denyTimetable=false,historyStorage=null}={}){
 if(operationPolicy===null){const {unpackDocument}=await import('../dist/model.js');keData=addFlightDetails(structuredClone(await unpackDocument(keData)));operationPolicy=operatingProofFor(keData);}
 const dom=new JSDOM(html,{url:'https://example.test/',pretendToBeVisual:true}),d=dom.window.document,calls=[];let release,deny=denyAsiana;const gate=new Promise(r=>release=r);
 globalThis.document=d;globalThis.Option=dom.window.Option;globalThis.localStorage=historyStorage??dom.window.localStorage;globalThis.location={reload:()=>{}};dom.window.HTMLDialogElement.prototype.showModal=function(){this.open=true;};dom.window.HTMLDialogElement.prototype.close=function(){this.open=false;};
 globalThis.fetch=async(url,options)=>{if(url.split('?')[0]==='./catalog.json')return Response.json(catalog);calls.push({url,options});if(url==='./timetable-reference.json')return denyTimetable||!timetableReference?new Response('',{status:404}):Response.json(timetableReference);if(url==='./operation-schedules.json')return denyOperation?new Response('',{status:503}):Response.json(operationPolicy);if(options?.signal?.aborted)throw options.signal.reason;if(url.split('?')[0].endsWith('/asiana.json')){if(holdAsiana)await gate;return deny?new Response('',{status:403}):Response.json(ozData);}if(url.includes('/ICN/')&&url.split('?')[0].endsWith('/europe.json'))return denyKorean?new Response('',{status:503}):Response.json(keData);return new Response('',{status:404});};
 const appModule=await import(new URL('../dist/app.js?test='+serial++,import.meta.url));
 return {d,w:dom.window,calls,release,refresh:()=>appModule.loadData(true),setKeData:value=>keData=value,denyKorean:()=>denyKorean=true,denyOperation:()=>denyOperation=true,setOperation:value=>operationPolicy=value,allow:()=>deny=false,ready:()=>waitFor(()=>!d.getElementById('app-screen').hidden),close:()=>dom.window.close()};
}
test('entry keeps main hidden until both airlines complete, then shows real 100-percent progress',async()=>{const p=await page({holdAsiana:true});try{await waitFor(()=>p.calls.some(c=>c.url.split('?')[0].endsWith('asiana.json')));assert.equal(p.d.getElementById('app-screen').hidden,true);assert.equal(p.d.getElementById('boot-screen').hidden,false);assert.ok(p.d.getElementById('boot-progress').value<100);p.release();await p.ready();assert.equal(p.d.getElementById('boot-progress').value,100);assert.equal(p.d.getElementById('boot-screen').hidden,true);assert.equal(p.calls.length,9);assert.ok(p.d.querySelectorAll('.route-card').length>0);}finally{p.release();p.close();}});
