 const values=new Map(),historyStorage={getItem:key=>values.get(key)??null,setItem:(key,value)=>values.set(key,value)},initial=await repeatReviewFixture(),changed=await repeatReviewFixture({allMatched:true});let p=await page({keData:initial,historyStorage});const originalCreate=URL.createObjectURL,originalRevoke=URL.revokeObjectURL;let exported;
