async function regionalReopenFixture(){
 const {unpackDocument}=await import('../dist/model.js'),body=await unpackDocument(ke),original=Object.values(body.records)[0];
 for(const [destination,month] of [['BKK','2026-12'],['BKK','2027-01'],['JFK','2027-01']]){const count=new Date(Date.UTC(+month.slice(0,4),+month.slice(5,7),0)).getUTCDate(),current={carrier:'KE',origin:'ICN',destination,month,sourceUpdatedAt:original.current.sourceUpdatedAt,collectedAt:original.current.collectedAt,dates:Array.from({length:count},(_,i)=>({date:month+'-'+String(i+1).padStart(2,'0'),status:'OBSERVED',...Object.fromEntries(TEST_FIELDS.map(f=>[f,f==='prestigeUpgrade']))}))};body.records['ICN-'+destination+'-'+month]={current,previous:null,success:original.success};}
 return body;
}
test('KE opens Europe and USA through the359-day booking horizon and retains a selected future month across airline tabs',async()=>{const p=await page();try{await p.ready();const {addDays}=await import('../dist/model.js'),start=p.d.getElementById('start').value,end=p.d.getElementById('end');assert.equal(end.value,addDays(start,359));assert.equal(end.max,addDays(start,359));assert.equal(p.d.getElementById('start').max,addDays(start,359));choose(p,'destination','FCO');choose(p,'month','2027-01');assert.equal(p.d.getElementById('month').value,'2027-01');p.d.getElementById('tab-oz').click();await waitFor(()=>p.d.getElementById('load-status').textContent.includes('104개'));assert.equal(end.value,addDays(start,359));p.d.getElementById('tab-ke').click();await waitFor(()=>p.d.getElementById('load-status').textContent.includes('72개'));choose(p,'destination','FCO');assert.equal(end.value,addDays(start,359));assert.equal(p.d.getElementById('month').value,'2027-01');assert.ok(p.d.querySelector('[data-date="2027-01-01"]'));}finally{p.close();}});
test('European and USA calendars reopen later dates while another KE region remains capped even after a forged future month selection',async()=>{const p=await page({keData:await regionalReopenFixture()});try{await p.ready();choose(p,'destination','FCO');choose(p,'month','2026-12');assert.equal(p.d.querySelector('[data-date="2026-12-18"]').disabled,false);assert.equal(p.d.querySelectorAll('#calendar-grid button').length,31);assert.equal(p.d.getElementById('next-month').disabled,false);choose(p,'destination','JFK');choose(p,'month','2027-01');assert.equal(p.d.querySelector('[data-date="2027-01-18"]').disabled,false);assert.equal(p.d.querySelector('#calendar-counts [data-field="prestigeUpgrade"] strong').textContent,'31일');choose(p,'destination','BKK');choose(p,'month','2026-12');assert.equal(p.d.querySelector('[data-date="2026-12-17"]').disabled,false);assert.equal(p.d.querySelector('[data-date="2026-12-18"]'),null);assert.equal(p.d.querySelectorAll('#calendar-grid button').length,17);assert.equal(p.d.getElementById('next-month').disabled,true);choose(p,'month','2027-01');assert.equal(p.d.getElementById('month').value,'2026-12');assert.equal(p.d.querySelector('[data-date="2027-01-01"]'),null);assert.ok([...p.d.querySelectorAll('#calendar-grid button')].every(e=>e.dataset.date<='2026-12-17'));choose(p,'destination','FCO');assert.equal(p.d.querySelectorAll('#calendar-grid button').length,31);}finally{p.close();}});
test('reopened KE form accepts December18 and rejects dates after359 days while Asiana keeps the same horizon',async()=>{const p=await page();try{await p.ready();const {addDays}=await import('../dist/model.js'),start=p.d.getElementById('start').value,end=p.d.getElementById('end'),calls=p.calls.length;choose(p,'destination','FCO');end.value='2026-12-18';p.d.getElementById('search-form').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(p.d.getElementById('form-error').hidden,true);const totals=p.d.getElementById('route-list').textContent;end.value=addDays(start,360);p.d.getElementById('search-form').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(p.d.getElementById('form-error').hidden,false);assert.match(p.d.getElementById('form-error').textContent,/359/);assert.equal(p.d.getElementById('route-list').textContent,totals);assert.equal(p.calls.length,calls);p.d.getElementById('tab-oz').click();await waitFor(()=>p.d.getElementById('load-status').textContent.includes('104개'));assert.equal(end.value,addDays(start,359));end.value=addDays(start,360);p.d.getElementById('search-form').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));assert.equal(p.d.getElementById('form-error').hidden,false);assert.match(p.d.getElementById('form-error').textContent,/359/);}finally{p.close();}});
test('KE homepage keeps the date range notice without the removed nonoperation explanation',async()=>{const p=await page();try{await p.ready();const notice=p.d.getElementById('ke-range-notice');assert.equal(notice.hidden,false);assert.equal(notice.getAttribute('role'),'note');assert.match(notice.textContent,/유럽.*미주.*대양주/);assert.match(notice.textContent,/12월 18일 이후/);assert.match(notice.textContent,/그 외|나머지/);assert.match(notice.textContent,/2026년 12월 17일까지/);assert.doesNotMatch(p.d.body.textContent,/대한항공 직접 운항·공동운항편을 함께 표시합니다|직접 운항편 수·금·일 출발 기준|좌석 표식 오류로 잠시 수정 중/);assert.equal(p.d.getElementById('ke-nonoperation-notice'),null);assert.equal(notice.querySelector('dialog'),null);}finally{p.close();}});


test('both airline screens omit excluded regions and cached destination routes while keeping the explicit removal notice',async()=>{
 const {unpackDocument}=await import('../dist/model.js'),keData=await unpackDocument(ke),ozData=await unpackDocument(oz);
 for(const [carrier,body] of [['KE',keData],['OZ',ozData]]){const template=Object.values(body.records)[0];for(const [origin,destination] of [['ICN','NRT'],['NRT','ICN'],['ICN','CAN'],['ICN','GMP'],['GMP','ICN']]){const value=structuredClone(template);Object.assign(value.current,{carrier,origin,destination});body.records[`${origin}-${destination}-${value.current.month}`]=value;}}
 const p=await page({keData,ozData});try{await p.ready();for(const carrier of ['KE','OZ']){if(carrier==='OZ'){p.d.getElementById('tab-oz').click();await waitFor(()=>p.d.body.dataset.carrier==='OZ'&&p.d.getElementById('load-status').classList.contains('ready'));}
  const regionValues=[...p.d.getElementById('region').options].map(option=>option.value),countryValues=[...p.d.getElementById('country').options].map(option=>option.value),airportValues=[...p.d.getElementById('destination').options].map(option=>option.value);
  assert.ok(!regionValues.includes('동북아시아'));assert.ok(!regionValues.includes('대한민국'));for(const code of ['JP','CN','KR'])assert.ok(!countryValues.includes(code));for(const code of ['NRT','CAN','GMP','CJU'])assert.ok(!airportValues.includes(code));assert.ok(airportValues.includes('CDG'));assert.ok(airportValues.includes('BKK'));
  const routes=[...p.d.querySelectorAll('.route-card')].map(card=>card.dataset.code);assert.ok(!routes.includes('NRT'));assert.ok(!routes.includes('CAN'));assert.ok(!routes.includes('GMP'));assert.ok(routes.includes('LHR'));
  const notice=p.d.getElementById('excluded-region-notice');assert.ok(notice);assert.equal(notice.hidden,false);assert.match(notice.textContent,/대한항공·아시아나/);assert.match(notice.textContent,/동북아·한국/);assert.match(notice.textContent,/조회 대상에서 제외/);
 }
 assert.ok(p.calls.every(call=>!call.url.split('?')[0].endsWith('/east_asia.json')&&!call.url.split('?')[0].endsWith('/korea.json')));
 }finally{p.close();}
});

test('actual Paris December review and February whole-weekday exclusion use raw stored flags regardless of operator and timetable evidence',async()=>{
 const source=JSON.parse(await readFile(new URL('fixtures/paris-v2-current-records.json',import.meta.url)));mock.timers.setTime(Math.max(...Object.values(source.records).map(record=>record.success))+1000);const p=await page({keData:source,operationPolicy:{schema:1,weeks:[]},timetableReference:uiTimetable({start:'2026-12-01',end:'2026-12-31',weekdays:[],noFlightWeekdays:[0,1,2,3,4,5,6]})});try{await p.ready();choose(p,'destination','CDG');choose(p,'month','2026-12');
 for(const date of ['2026-12-20','2026-12-27']){const day=p.d.querySelector(`[data-date="${date}"]`);assert.equal(day.classList.contains('day-review'),true);assert.equal(day.querySelectorAll('.day-type').length,2);assert.match(day.textContent,/확인필요/);}
 const unknown=p.d.querySelector('[data-date="2026-12-13"]');assert.equal(unknown.classList.contains('day-review'),false);assert.equal(unknown.classList.contains('day-unknown'),true);assert.equal(unknown.querySelectorAll('.day-type').length,0);p.d.querySelector('[data-date="2026-12-20"]').click();assert.match(p.d.getElementById('day-markers').textContent,/확인필요/);assert.equal(p.d.querySelectorAll('.flight-group .flight-detail').length,0);assert.equal(p.d.querySelectorAll('.timetable-day-reference').length,0);p.d.getElementById('day-dialog').close();
 choose(p,'month','2027-02');for(const date of ['2027-02-07','2027-02-14','2027-02-21','2027-02-28']){const day=p.d.querySelector(`[data-date="${date}"]`);assert.equal(day.querySelectorAll('.day-type').length,0);assert.match(day.textContent,/대한항공 비운항/);assert.equal(day.classList.contains('day-review'),false);}
 const december=p.d.querySelector('#repeat-history-body tr[data-month="2026-12"][data-result="REVIEW"]');assert.ok(december);assert.match(december.textContent,/2\/2/);assert.match(december.textContent,/2027년 1월 참고/);assert.match(december.textContent,/참고월 자료 없음/);const february=p.d.querySelector('#repeat-history-body tr[data-month="2027-02"][data-result="EXCLUDED"]');assert.ok(february);assert.match(february.textContent,/4\/4/);
 }finally{p.close();mock.timers.setTime(new Date('2026-10-31T14:59:00Z').getTime());}
});

test('real partial Rome October shows consistent two-line grey cells, reference month, corrected totals and current refresh decisions',async()=>{
 const {unpackDocument}=await import('../dist/model.js');
 const source=await unpackDocument(JSON.parse(await readFile(new URL('fixtures/rome-reference-live.json',import.meta.url))));
 mock.timers.setTime(Math.max(...Object.values(source.records).map(r=>r.success))+1000);
 const p=await page({keData:source,operationPolicy:{schema:1,weeks:[]}});
 try{
  await p.ready();choose(p,'destination','FCO');choose(p,'month','2027-10');
  assert.equal(p.d.querySelectorAll('#calendar-grid .day-review').length,0);
  for(const date of ['2027-10-01','2027-10-03','2027-10-05','2027-10-07','2027-10-24']){
   const cell=p.d.querySelector(`[data-date="${date}"]`);assert.equal(cell.querySelectorAll('.day-type').length,0);
   assert.equal(cell.querySelector('.ke-nonoperation-title').textContent,'대한항공 비운항');assert.equal(cell.querySelector('.ke-nonoperation-codeshare').textContent,'공동운항 있을 수 있음');assert.doesNotMatch(cell.textContent,/비운항 추정/);
  }
  assert.equal(p.d.querySelector('[data-date="2027-10-29"] .ke-nonoperation'),null);
  assert.equal(p.d.querySelector('#calendar-counts [data-field="prestigeAward"] strong').textContent,'0일');assert.equal(p.d.querySelector('#calendar-counts [data-field="prestigeUpgrade"] strong').textContent,'2일');
  const summary=p.d.getElementById('repeat-marker-summary');assert.ok(p.d.getElementById('calendar-grid').compareDocumentPosition(summary)&4);assert.match(summary.textContent,/2027년 9월/);
  p.d.querySelector('[data-date="2027-10-01"]').click();assert.match(p.d.getElementById('day-markers').textContent,/2027년 9월/);assert.match(p.d.getElementById('day-markers').textContent,/2027-09-03/);p.d.getElementById('day-dialog').close();
  choose(p,'month','2026-12');assert.ok(p.d.querySelector('[data-date="2026-12-18"] .ke-nonoperation'));assert.equal(p.d.querySelector('[data-date="2026-12-17"] .ke-nonoperation'),null);assert.match(summary.textContent,/2027년 1월/);
  const revised=structuredClone(source);for(const item of Object.values(revised.records)){const r=item.current;if(r.origin==='ICN'&&r.destination==='FCO'&&r.month==='2027-09')for(const d of r.dates)if(new Date(d.date+'T00:00:00Z').getUTCDay()===0)d.prestigeAward=false;}
  choose(p,'month','2027-10');p.setKeData(revised);await p.refresh();
  const sunday=p.d.querySelector('[data-date="2027-10-03"]');assert.ok(sunday.classList.contains('day-review'));assert.equal(sunday.querySelector('.ke-nonoperation'),null);assert.ok(sunday.querySelector('.day-type'));
 }finally{p.close();mock.timers.setTime(new Date('2026-10-31T14:59:00Z').getTime());}
});
test('live Amsterdam November and all loaded pre-December18 calendars keep original markers without review or exclusion',async()=>{
 const {unpackDocument}=await import('../dist/model.js'),source=await unpackDocument(JSON.parse(await readFile(new URL('fixtures/europe-original-live.json',import.meta.url))));
 mock.timers.setTime(Math.max(...Object.values(source.records).map(r=>r.success))+1000);
 const p=await page({keData:source,operationPolicy:{schema:1,weeks:[]}});
 try{await p.ready();choose(p,'destination','AMS');choose(p,'month','2026-11');assert.equal(p.d.querySelectorAll('#calendar-grid .day-review,#calendar-grid .ke-nonoperation').length,0);assert.equal(p.d.querySelector('#calendar-counts [data-field="prestigeAward"] strong').textContent,'4일');assert.equal(p.d.querySelector('#calendar-counts [data-field="prestigeUpgrade"] strong').textContent,'7일');
  for(const direction of ['out','back']){p.d.getElementById('direction-'+direction).click();for(const month of ['2026-11','2026-12']){choose(p,'month',month);const key=(direction==='out'?'ICN-AMS-':'AMS-ICN-')+month;for(const d of source.records[key].current.dates.filter(d=>d.date>='2026-11-03'&&d.date<='2026-12-17')){const cell=p.d.querySelector(`[data-date="${d.date}"]`);assert.equal(cell.classList.contains('day-review'),false);assert.equal(cell.querySelector('.ke-nonoperation'),null);assert.deepEqual([...cell.querySelectorAll('.day-type')].map(e=>e.textContent),d.status==='OBSERVED'?['prestigeAward','prestigeUpgrade','firstCombined'].flatMap((f,i)=>d[f]?[['보너스','승급','퍼스트'][i]]:[]):[]);}}}
 }finally{p.close();mock.timers.setTime(new Date('2026-10-31T14:59:00Z').getTime());}
});
